const input = $json.body ?? $json;
const report = input.url_check_report ?? {};
const prompt = `Analyze only the supplied website inspection. Do not invent facts.
Objective: ${input.objective ?? ''}
URL: ${input.product_url ?? ''}
HTTP status: ${report.status_code ?? ''}
Title: ${report.title ?? ''}
Meta description: ${report.meta_description ?? ''}
H1: ${(report.h1 ?? []).join(', ')}
Links: ${report.link_count ?? 0}
Technical signals: ${(report.technical_signals ?? []).join(', ')}
Notes: ${(report.notes ?? []).join('; ')}
Return JSON with keys: executive_summary, product_positioning, target_audience, value_propositions, strengths, risks_and_gaps, recommended_channels, next_internal_actions, confidence.`;
return [{ json: { task_id: input.task_id ?? '', product_url: input.product_url ?? '', prompt } }];

const source = $json;
const raw = source.message?.content ?? source.text ?? source.response ?? source;
let analysis = raw;
if (typeof raw === 'string') {
  const clean = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  try { analysis = JSON.parse(clean); } catch { analysis = { executive_summary: clean, product_positioning: '', target_audience: [], value_propositions: [], strengths: [], risks_and_gaps: ['AI returned non-JSON text; review required'], recommended_channels: [], next_internal_actions: [], confidence: 'low' }; }
}
return [{ json: { provider: 'n8n-local', model: 'configured-n8n-ai', analysis } }];
